<?php require_once __DIR__.'/includes/bootstrap.php';$pageTitle='Community Portal';$name=logged_in()?($_SESSION['user']['name']??'Resident'):'Guest visitor';$updates=rows($pdo,'SELECT title,published_at FROM public_updates WHERE is_published=1 ORDER BY published_at DESC LIMIT 5');require __DIR__.'/includes/header.php';?><main><section class="hero"><div><span style="color:var(--teal);letter-spacing:1.5px;font-weight:bold">COMMUNITY PORTAL</span><h1>Good day, <?= h($name) ?>.</h1><p>One place for local information, services, and community participation.</p></div><?php if(!logged_in()):?><div class="notice"><strong>Guest mode</strong><br>You're browsing public content. Sign in to save items, subscribe to alerts, and submit requests.</div><?php endif;?></section><section class="section"><div class="grid"><a class="panel" href="community-profile.php"><h2>Community Profile</h2><p>Meet the barangay, learn its history, and view current officials.</p></a><a class="panel" href="census-statistics.php"><h2>Census & Statistics</h2><p>Browse population, household, and demographic information.</p></a><a class="panel" href="services-programs.php"><h2>Services & Programs</h2><p>Find schedules, contact details, and current programs.</p></a><a class="panel" href="official-documents.php"><h2>Official Documents</h2><p>Browse public records and downloadable forms.</p></a></div></section><section class="section grid two"><article class="panel"><h2>Recent updates</h2><?php if(!$updates):?><p>No updates have been published yet.</p><?php else:foreach($updates as $u):?><p><strong style="color:var(--teal)"><?= h(strtoupper(date('M d',strtotime($u['published_at']??'now')))) ?></strong> <?= h($u['title']) ?></p><?php endforeach;endif;?></article><article class="panel"><h2><?= logged_in()?'Your account':'Make it yours' ?></h2><p><?= logged_in()?'Save pages, subscribe to alerts, and track requests.':'Create an account to keep important pages close and track every request.' ?></p><?php if(!logged_in()):?><a class="button" href="register.php">Create account</a><?php endif;?></article></section></main><?php require __DIR__.'/includes/footer.php';?>
